var r=UnityEditor.Build.Reporting.BuildReport.GetLatestReport();if(r==null)throw new Exception("No build report");
var messages=r.steps.SelectMany(s=>s.messages.Where(m=>m.type==LogType.Warning || m.type==LogType.Error).Select(m=>new {step=s.name,type=m.type.ToString(),content=m.content})).ToArray();
System.IO.File.WriteAllText("/home/teknetik/code/ao2/unity/evidence/quality/20260926/release-build-warnings.json",Newtonsoft.Json.JsonConvert.SerializeObject(new {output=r.summary.outputPath,warnings=r.summary.totalWarnings,errors=r.summary.totalErrors,messages=messages},Newtonsoft.Json.Formatting.Indented));
return new {warnings=r.summary.totalWarnings,errors=r.summary.totalErrors,recordedMessages=messages.Length,sceneDirty=UnityEditor.SceneManagement.EditorSceneManager.GetActiveScene().isDirty};
